&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de paladin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_paladin_0&quot; href=&quot;#Les_arch&#233;types_de_paladin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-B&#233;ni-(Paladin).html&quot; title=&quot;Bouclier b&#233;ni&quot;&gt;Bouclier b&#233;ni&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Temple-(Paladin).html&quot; title=&quot;Champion du temple&quot;&gt;Champion du temple&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Certains paladins utilisent leurs dons pour faire jaillir la lumi&#232;re sacr&#233;e qui brille dans leurs &#226;mes. Ces paladins passent la majeure partie de leur vie &#224; guider les autres vers le droit chemin en utilisant la puret&#233; et la r&#233;demption comme armes. Leur qu&#234;te demande une grande patience et a un prix &#233;lev&#233;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Le guerrier de la lumi&#232;re sainte poss&#232;de les aptitudes de classe suivantes.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de la foi (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_la_foi_Sur_0&quot; href=&quot;#Pouvoir_de_la_foi_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#41&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Paladin, Guerrier de la lumi&#232;re sainte : &#192; quel type de lumi&#232;re correspond l&#39;&#171; aura lumineuse &#187; de l&#39;arch&#233;type guerrier de la lumi&#232;re sainte (page 117), dans le cadre de l&#39;interaction entre la lumi&#232;re et les t&#233;n&#232;bres ? Y&#39;a-t-il une limite au nombre de fois o&#249; le paladin peut activer cette capacit&#233; ? La capacit&#233; de niveau 12 affecte-t-elle le paladin, ou seulement ses alli&#233;s ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;La &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;capacit&#233;&lt;/a&gt;&lt;/u&gt; compte comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt; jusqu&#39;au niveau 8, apr&#232;s quoi elle compte comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt;. Activer l&#39;&#171; aura lumineuse &#187; d&#233;pense une utilisation de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt;. Tous les effets de l&#39;aura affecte le paladin autant que ses alli&#233;s (le jeu consid&#232;re qu&#39;un personnage est toujours son propre alli&#233;). La mise &#224; jour du MRA inclura ces clarifications.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Au niveau 4, un guerrier de la lumi&#232;re sainte apprend &#224; utiliser le pouvoir de sa foi pour accro&#238;tre ses d&#233;fenses et aider ses alli&#233;s. Cette capacit&#233; de classe remplace la capacit&#233; de lancement de &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#SORTS&quot; title=&quot;Le paladin&quot;&gt;sorts&lt;/a&gt; des paladins ordinaires. Un guerrier de la lumi&#232;re sainte ne gagne aucun sort ni capacit&#233; de lancement de sorts : il ne poss&#232;de aucun &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; et ne peut utiliser ni objets &#224; potentiel magique ni objets &#224; fin d’incantation.&lt;br /&gt;&lt;br /&gt;Au niveau 4, le guerrier de la lumi&#232;re sainte acquiert une utilisation quotidienne suppl&#233;mentaire de sa capacit&#233; d’&lt;a class=&quot;pagelink&quot; href=&quot;Paladin#Impositiondesmains.html&quot; title=&quot;Imposition des mains&quot;&gt;imposition des mains&lt;/a&gt;. Il en gagne une autre tous les quatre niveaux au-del&#224; du niveau 4. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, il peut se servir d&#39;une utilisation quotidienne d&#39;imposition des mains pour faire appel au pouvoir de sa foi. Une aura lumineuse de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de rayon &#233;mane alors de lui. Tous les alli&#233;s situ&#233;s dans cette zone (y compris le guerrier de la lumi&#232;re sainte) re&#231;oivent un bonus de moral de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; ainsi qu’aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Degats.html&quot; title=&quot;jet de d&#233;g&#226;ts&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;sauvegarde&lt;/a&gt; contre la terreur qui persiste tant qu’ils restent dans la zone lumineuse. L’aura reste active pendant 1 minute.&lt;br /&gt;&lt;br /&gt;Au niveau 8, l’aura lumineuse soigne le paladin et ses alli&#233;s de 1d4 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; de caract&#233;ristiques comme le sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt;. Chaque cr&#233;ature ne peut &#234;tre soign&#233;e de la sorte qu’une seule fois par jour.&lt;br /&gt;&lt;br /&gt;Au niveau 12, l’aura lumineuse fonctionne comme un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt; pour tout ce qui touche aux cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-&#192;-La-Lumi&#232;re-(Capacit&#233;).html&quot; title=&quot;Sensibilit&#233; &#224; la lumi&#232;re&quot;&gt;sensibles &#224; la lumi&#232;re&lt;/a&gt;. De plus, elle donne aux alli&#233;s situ&#233;s dans la zone une r&#233;sistance de 10 points &#224; un type d’&#233;nergie (choisi par le guerrier de la lumi&#232;re sainte lors de l’activation de cette capacit&#233;).&lt;br /&gt;&lt;br /&gt;Au niveau 16, l’aura lumineuse prot&#232;ge le guerrier de la lumi&#232;re sainte et ses alli&#233;s contre les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt;. Chaque coup critique &#224; l’encontre du guerrier de la lumi&#232;re sainte ou d’un de ses alli&#233;s situ&#233; dans la zone de l’aura a 25% de chance d’&#234;tre trait&#233; comme une attaque r&#233;ussie normale. Cet effet ne se cumule pas avec les autres protections similaires (comme la propri&#233;t&#233; d’armure de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#D&#233;fense&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;d&#233;fense&lt;/a&gt;&lt;/i&gt;).&lt;br /&gt;&lt;br /&gt;Au niveau 20, l’aura lumineuse s’&#233;tend sur un rayon de 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). De plus, tous les bonus qu’elle offre augmentent. Le bonus moral &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Degats.html&quot; title=&quot;jet de d&#233;g&#226;ts&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; et de&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt; sauvegarde&lt;/a&gt; contre la terreur passe &#224; +2. La quantit&#233; d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; gu&#233;rie passe &#224; 2d4. La r&#233;sistance contre un type d’&#233;nergie passe &#224; 20 points. Et, finalement, la protection contre les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; passe &#224; 50%.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Lumi&#232;re &#233;clatante (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Lumi&#232;re_&#233;clatante_Sur_1&quot; href=&quot;#Lumi&#232;re_&#233;clatante_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 14, un guerrier de la lumi&#232;re sainte peut projeter un rayonnement de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de rayon de pure lumi&#232;re blanche par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Les cr&#233;atures Mauvaises situ&#233;es dans ce rayonnement subissent 1d6 points de d&#233;g&#226;ts par tranche de 2 niveaux du paladin et sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;aveugle&quot;&gt;aveugl&#233;es&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;dragons mal&#233;fiques&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;Ext&#233;rieurs mal&#233;fiques&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants mal&#233;fiques&lt;/a&gt; sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;aveugle&quot;&gt;aveugl&#233;s&lt;/a&gt; pendant 1d4 rounds en cas d’&#233;chec du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt;. Un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; permet de diviser les d&#233;g&#226;ts par deux et d’annuler l’aveuglement. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ce jet vaut 10 + la moiti&#233; du niveau du guerrier de la lumi&#232;re sainte + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Les cr&#233;atures d’alignement Bon situ&#233;es dans ce rayonnement sont gu&#233;ries de 1d6 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;points de vie&lt;/a&gt; par 2 niveaux du paladin et re&#231;oivent un bonus sacr&#233; de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;tests&lt;/a&gt; de caract&#233;ristiques, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; et tests de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Testsdecompetences.html&quot; title=&quot;test de comp&#233;tence&quot;&gt;comp&#233;tence&lt;/a&gt; pendant 1 round. Un guerrier de la lumi&#232;re sainte peut utiliser cette capacit&#233; une fois par jour au niveau 14 et une fois de plus par jour aux niveaux 17 et 20. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEFOI&quot; title=&quot;Le paladin&quot;&gt;Aura de foi&lt;/a&gt;.
